197		}
198		defer func() { _ = file.Close() }()
199	
200		var pos TranscriptPosition
201		reader := bufio.NewReader(file)
202	
203		for {
204			lineBytes, err := reader.ReadBytes('\n')
205			if err != nil && err != io.EOF {
