209			if len(lineBytes) == 0 {
210				if err == io.EOF {
211					break
212				}
213				continue
214			}
215	
216			pos.LineCount++
217	
218			// Parse line to extract UUID (only from user/assistant messages, not summaries)
219			var line transcriptLine
