595	// ClearSessionState removes the session state file for the given session ID.
596	func ClearSessionState(ctx context.Context, sessionID string) error {
597		// Validate session ID to prevent path traversal
598		if err := validation.ValidateSessionID(sessionID); err != nil {
599			return fmt.Errorf("invalid session ID: %w", err)
600		}
601	
602		stateDir, err := getSessionStateDir(ctx)
603		if err != nil {
604			return fmt.Errorf("failed to get session state directory: %w", err)
605		}
606	
607		// Remove all files for this session (state .json, .model hint, any future hint files).
608		matches, _ := filepath.Glob(filepath.Join(stateDir, sessionID+".*")) //nolint:errcheck // pattern is always valid
609		for _, f := range matches {
610			_ = os.Remove(f)
611		}
612	
613		// Intentionally do NOT remove the per-session lock file under
614		// entire-session-locks/. POSIX flock and Windows LockFileEx are bound to
615		// the inode/file-handle: unlinking the lock path while another process
616		// holds it lets a third caller recreate the file and acquire an
617		// independent lock, breaking mutual exclusion. Lock files are 0-byte
618		// sentinels and session IDs aren't reused, so leaving them in place is
619		// harmless. Bulk cleanup happens via RemoveAll on uninstall.
620		return nil
